#include <stdio.h>
#include <math.h>

int main(void) {
    double P, i, n;
    scanf("%lf %lf %lf", &P, &i, &n);
    printf("%.2f\n", P * pow(1.0 + i / 100.0, n));
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double x1, y1, x2, y2;
    scanf("%lf %lf %lf %lf", &x1, &y1, &x2, &y2);
    double dist = sqrt((x2-x1)*(x2-x1) + (y2-y1)*(y2-y1));
    printf("%.4f\n", dist);
    return 0;
}

#include <stdio.h>

int main(void) {
    int s;
    scanf("%d", &s);
    int hh = s / 3600;
    int mm = (s % 3600) / 60;
    int ss = s % 60;
    printf("%02d:%02d:%02d\n", hh, mm, ss);
    return 0;
}

#include <stdio.h>

int main(void) {
    double k;
    scanf("%lf", &k);
    double c = k - 273.15;
    double f = c * 9.0 / 5.0 + 32.0;
    printf("%.2f\n%.2f\n", c, f);
    return 0;
}

#include <stdio.h>

int main(void) {
    double l, w, h;
    scanf("%lf %lf %lf", &l, &w, &h);
    printf("%.2f\n", l * w * h);
    printf("%.2f\n", 2.0 * (l*w + l*h + w*h));
    return 0;
}

#include <stdio.h>

int main(void) {
    int notas, moedas;
    scanf("%d %d", &notas, &moedas);
    printf("%.2f\n", notas * 50.0 + moedas * 0.25);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double a, b, c;
    scanf("%lf %lf %lf", &a, &b, &c);
    double delta = b*b - 4.0*a*c;
    double x1 = (-b + sqrt(delta)) / (2.0*a);
    double x2 = (-b - sqrt(delta)) / (2.0*a);
    printf("%.4f\n%.4f\n%.4f\n", delta, x1, x2);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    printf("%d\n", (n / 100) + ((n / 10) % 10) + (n % 10));
    return 0;
}
